package akogen.fabric.v6;
import com.google.gson.*;import java.util.*;import java.io.*;import java.util.zip.*;
public final class Assets{
 public static final Map<String,byte[]> files=new HashMap<String,byte[]>();public static final List<Entry> entries=new ArrayList<Entry>();public static final String[] groups={"All","Verity","Tung Tung Sahur","Code Geass","Evangelion","Pets","Dingiller"};
 public static class Entry{public int id;public String name,group,file,slot;public JsonObject config;public Models.Model model;public final Map<String,Models.Mat> poses=new HashMap<String,Models.Mat>();public Object texture,layer,preview;public double px,py,pz,yaw,speed,lastTime,groundY,groundAt,animAge,ownerX,ownerZ,followYaw,targetX,targetZ;public boolean placed,following,running;}
 public static void load(byte[] data)throws Exception{int total=0;try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(data))){ZipEntry e;byte[] buf=new byte[8192];while((e=z.getNextEntry())!=null){if(e.isDirectory())continue;if(e.getName().contains(".."))throw new IOException("Invalid asset path");ByteArrayOutputStream out=new ByteArrayOutputStream();int n;while((n=z.read(buf))>0){total+=n;if(total>33554432)throw new IOException("Asset pack too large");out.write(buf,0,n);}files.put(e.getName(),out.toByteArray());}}
 JsonArray cat=json("assets/lunar/dev_cosmetics.json").getAsJsonArray();int i=0;for(JsonElement el:cat){JsonObject o=el.getAsJsonObject();int id=i++;String name=o.get("name").getAsString();if(name.equals("Verity")||name.equals("Geass Hat"))continue;Entry e=new Entry();e.id=id;e.name=name.equals("Tung Watch")?"Tung Tung Watch":name;e.file=o.get("file").getAsString();e.group=e.file.contains("dingiller/")?"Dingiller":e.file.contains("code_geass/")?"Code Geass":e.file.contains("evangelion/")?"Evangelion":e.file.contains("pets/")?"Pets":name.startsWith("Tung")?"Tung Tung Sahur":"Verity";
 if(e.file.endsWith(".png")){e.config=new JsonObject();e.config.addProperty("texture",e.file);e.slot="cloak";}else{e.config=json(path(e.file)).getAsJsonObject();String type=str(e.config,"type",o.get("category").getAsString());e.slot=type;if(type.equals("pet"))e.slot="shoulder";if(name.contains("Wings"))e.slot="wings";if(name.contains("Aura"))e.slot="aura";if(name.contains("Balloon"))e.slot="balloon";if(name.contains("Watch"))e.slot="wrist";if(name.contains("Shoes"))e.slot="shoes";if(name.startsWith("Flying"))e.slot="flying";}
 entries.add(e);}}
 public static String str(JsonObject o,String key,String fallback){return o.has(key)&&o.get(key).isJsonPrimitive()?o.get(key).getAsString():fallback;}
 public static String path(String uri){if(uri.startsWith("assets/"))return uri;int p=uri.indexOf(':');return p<0?uri:"assets/"+uri.substring(0,p)+"/"+uri.substring(p+1);}
 public static JsonElement json(String key)throws Exception{byte[] v=files.get(key);if(v==null)throw new FileNotFoundException(key);return new JsonParser().parse(new String(v,"UTF-8"));}
 public static void prepare(Entry e)throws Exception{if(e.model==null)e.model=Models.load(e);if(e.texture==null){String name=texture(e.config.get("texture"));if(name==null)throw new IOException("Texture missing for "+e.name);byte[] png=files.get(path(name));if(png==null)throw new FileNotFoundException(name);Object image=Names.call(Names.type("com/mojang/blaze3d/platform/NativeImage"),"read",new ByteArrayInputStream(png));Object tex=Names.create("net/minecraft/client/renderer/texture/DynamicTexture",(java.util.function.Supplier<String>)()->"Akogen "+e.name,image);Object id=Names.call(Names.type("net/minecraft/resources/Identifier"),"fromNamespaceAndPath","akogen","cosmetic/"+e.id);Names.call(Names.call(Session.mc,"getTextureManager"),"register",id,tex);e.texture=id;e.layer=Names.call(Names.type("net/minecraft/client/renderer/rendertype/RenderTypes"),"entityCutoutNoCull",id);}}

 public static Object preview(Entry e)throws Exception{if(e.preview==null){byte[] bytes=files.get("assets/akogen/previews/"+e.id+".png");if(bytes==null)return null;Object image=Names.call(Names.type("com/mojang/blaze3d/platform/NativeImage"),"read",new ByteArrayInputStream(bytes));Object texture=Names.create("net/minecraft/client/renderer/texture/DynamicTexture",(java.util.function.Supplier<String>)()->"Akogen preview "+e.name,image);Object id=Names.call(Names.type("net/minecraft/resources/Identifier"),"fromNamespaceAndPath","akogen","preview/"+e.id);Names.call(Names.call(Session.mc,"getTextureManager"),"register",id,texture);e.preview=id;}return e.preview;}
 static String texture(JsonElement v){if(v==null)return null;if(v.isJsonPrimitive())return v.getAsString();if(v.isJsonObject())for(Map.Entry<String,JsonElement>x:v.getAsJsonObject().entrySet()){if(x.getKey().contains(":"))return x.getKey();String s=texture(x.getValue());if(s!=null&&s.contains(":"))return s;}if(v.isJsonArray())for(JsonElement x:v.getAsJsonArray()){String s=texture(x);if(s!=null)return s;}return null;}
}
